async function auth(force=false){if(!force&&session?.expires_at>Date.now()/1000+60)return;const refresh=session?.refresh_token;const r=await fetch(`${config.url}/auth/v1/${refresh?'token?grant_type=refresh_token':'signup'}`,{method:'POST',headers:{apikey:config.key,'Content-Type':'application/json'},body:JSON.stringify(refresh?{refresh_token:refresh}:{data:{display_name:'Guest'}})});const s=await r.json();if(!r.ok)throw Error(s.msg||s.message||s.error_description||'Guest sign-in failed. Enable anonymous sign-ins in Supabase.');session={...s,expires_at:Date.now()/1000+s.expires_in};localStorage.setItem('forma-session',JSON.stringify(session))}
async function api(path,method='GET',body){await auth();const r=await fetch(`${config.url}/rest/v1/${path}`,{method,headers:{apikey:config.key,Authorization:`Bearer ${session.access_token}`,'Content-Type':'application/json',Prefer:'return=representation'},...(body===undefined?{}:{body:JSON.stringify(body)})});if(!r.ok){let e=await r.json().catch(()=>({message:'Unable to reach Supabase'}));throw Error(e.message||'Database request failed')}return r.status===204?null:r.json()}
async function load(){if(!cloud()){data=JSON.parse(localStorage.getItem('forma-demo')||'null')||seed();persist();return}await auth();const [tasks,members,labels,comments,activity]=await Promise.all([api('tasks?select=*,task_assignees(member_id),task_labels(label_id)&order=created_at.asc'),api('team_members?select=*&order=created_at.asc'),api('labels?select=*&order=created_at.asc'),api('comments?select=*&order=created_at.asc'),api('task_activity?select=*&order=created_at.asc')]);data={tasks:tasks.map(t=>({...t,assignee_ids:t.task_assignees.map(a=>a.member_id),label_ids:t.task_labels.map(a=>a.label_id)})),members,labels,comments,activity}}
function log(id,body){data.activity.push({id:uuid(),task_id:id,body,created_at:new Date().toISOString()})}
async function saveTask(t){const old=data.tasks.find(x=>x.id===t.id);if(cloud()){await api('rpc/save_task','POST',{p_task:{id:t.id,title:t.title,description:t.description,status:t.status,priority:t.priority,due_date:t.due_date||null},p_assignees:t.assignee_ids,p_labels:t.label_ids});await load()}else{if(old){if(old.status!==t.status)log(t.id,`Moved from ${statusName(old.status)} → ${statusName(t.status)}`);if(['title','description','priority','due_date'].some(k=>old[k]!==t[k]))log(t.id,'Updated task details');if(JSON.stringify(old.assignee_ids)!==JSON.stringify(t.assignee_ids))log(t.id,'Updated assignees');if(JSON.stringify(old.label_ids)!==JSON.stringify(t.label_ids))log(t.id,'Updated labels');data.tasks=data.tasks.map(x=>x.id===t.id?t:x)}else{data.tasks.push({...t,created_at:new Date().toISOString()});log(t.id,'Created this task')}persist()}}
function filtered(){return data.tasks.filter(t=>(!search||t.title.toLowerCase().includes(search.toLowerCase()))&&(!filters.priority||t.priority===filters.priority)&&(!filters.assignee||t.assignee_ids.includes(filters.assignee))&&(!filters.label||t.label_ids.includes(filters.label)))}
const countComments=t=>data.comments.filter(c=>c.task_id===t.id).length;
function due(t){if(!t.due_date)return '';const overdue=t.status!=='done'&&t.due_date<today(),soon=t.status!=='done'&&t.due_date>=today()&&t.due_date<=offsetDate(2);return `<span class="due ${overdue?'overdue':soon?'soon':''}" title="${overdue?'Overdue':soon?'Due soon':'Due date'}">${icon('calendar')}${t.due_date===today()?'Today':t.due_date===offsetDate(1)?'Tomorrow':fmtDate(t.due_date)}</span>`}
function tags(t){return t.label_ids.map(id=>data.labels.find(l=>l.id===id)).filter(Boolean).map(l=>`<span class="tag" style="--tagcolor:${esc(l.color)}">${esc(l.name)}</span>`).join('')}
function card(t){return `<article class="card" draggable="true" tabindex="0" role="button" aria-label="Open ${esc(t.title)}" data-task="${t.id}"><div class="card-top"><div class="tags">${tags(t)}</div><span class="priority-icon ${t.priority}" title="${t.priority} priority">${icon('flag')}</span></div><h3>${esc(t.title)}</h3>${t.description?`<p>${esc(t.description)}</p>`:''}<div class="card-foot">${due(t)}${countComments(t)?`<span class="comment-count">${icon('comment')}${countComments(t)}</span>`:''}<div class="avatar-stack">${t.assignee_ids.map(id=>avatar(data.members.find(m=>m.id===id))).join('')}</div></div></article>`}
function boardContent(){const tasks=filtered();if(busy)return '<div class="loading">Loading your workspace…</div>';if(loadError)return `<div class="notice" role="alert">${esc(loadError)} <button class="btn" data-action="retry">Try again</button><button class="btn" data-action="connect">Connection settings</button></div>`;if(view==='list')return `<div class="list"><table><thead><tr><th>Task</th><th>Status</th><th>Priority</th><th>Assignees</th><th>Due date</th></tr></thead><tbody>${tasks.map(t=>`<tr tabindex="0" data-task="${t.id}" role="button" aria-label="Open ${esc(t.title)}"><td>${esc(t.title)}</td><td>${statusName(t.status)}</td><td>${esc(t.priority)}</td><td>${t.assignee_ids.map(id=>avatar(data.members.find(m=>m.id===id))).join('')}</td><td>${due(t)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No tasks found. Try adjusting your filters or add a new task.</td></tr>'}</tbody></table></div>`;return `<div class="board">${statuses.map(([s,name,color])=>`<section class="column" data-status="${s}" aria-label="${name}"><div class="col-head"><span class="status-dot" style="--status:${color}"></span>${name}<span class="col-count">${tasks.filter(t=>t.status===s).length}</span><button class="icon-btn" data-action="new" data-status="${s}" aria-label="Add task to ${name}">${icon('plus')}</button></div><div class="cards">${tasks.filter(t=>t.status===s).map(card).join('')||'<div class="empty">A little space for what’s next.<br>Add a task or drop one here.</div>'}</div><button class="add-card" data-action="new" data-status="${s}">${icon('plus')} Add task</button></section>`).join('')}</div>`}
function render(){const total=data.tasks.length,completed=data.tasks.filter(t=>t.status==='done').length,overdue=data.tasks.filter(t=>t.status!=='done'&&t.due_date&&t.due_date<today()).length,progress=data.tasks.filter(t=>t.status==='in_progress').length;
$('#app').innerHTML=`<div class="app"><aside class="sidebar"><div class="brand"><span class="brandmark"><i></i><i></i></span>forma<span style="color:#87ae99">.</span></div><div class="workspace"><div class="workspace-icon">S</div><div><strong>Studio workspace</strong><span>Your space to make things</span></div></div><div class="smallcap">WORKSPACE</div><button class="nav ${page==='board'?'active':''}" data-page="board">${icon('board')} Project board <span class="count">${total}</span></button><button class="nav ${page==='team'?'active':''}" data-page="team">${icon('team')} Team members</button><button class="nav ${page==='labels'?'active':''}" data-page="labels">${icon('flag')} Labels</button><div class="section"><div class="smallcap">YOUR TEAM <span style="float:right">${data.members.length}</span></div><div class="teamlist">${data.members.map(m=>`<div class="person">${avatar(m)}<span>${esc(m.name)}</span><span class="dot"></span></div>`).join('')||'<p class="empty">Make room for your team.</p>'}<button class="team-add" data-action="member">${icon('plus')} Add member</button></div></div><div class="sidebar-bottom"><button class="nav" data-action="help">${icon('help')} A little help</button><div class="demo-note"><strong><span class="green-dot"></span>${cloud()?'Supabase connected':'Your local playground'}</strong>${cloud()?'Your tasks belong to your guest session.':'Try things out. Changes are saved in this browser.'}<button data-action="connect">${cloud()?'Connection settings':'Connect to Supabase'} ${icon('arrow')}</button></div><div class="profile"><span class="avatar" style="--color:#708e7b">Y</span><div>You<small>${cloud()?'Private guest session':'Guest · Demo workspace'}</small></div><button class="icon-btn" data-action="connect" aria-label="Workspace settings" style="margin-left:auto">${icon('settings')}</button></div></div></aside><main class="main"><header class="topbar"><div class="mobile-logo">forma.</div><div class="breadcrumbs">Workspace ${icon('chevron')} <strong>${page==='team'?'Team members':page==='labels'?'Labels':'Project board'}</strong></div><div class="top-actions"><span style="font-size:11px">${new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</span><button class="icon-btn" data-page="team" aria-label="Team members">${icon('team')}</button><button class="icon-btn" data-action="connect" aria-label="Connection settings">${icon('settings')}</button><span class="avatar" style="--color:#708e7b">Y</span></div></header><div class="content"><div class="eyebrow">A LITTLE CLARITY. A LOT OF POSSIBILITY.</div><div class="heading"><div><h1>${page==='team'?'Better, together.':page==='labels'?'Everything in its place.':'Project board'}</h1><p class="subtitle">${page==='team'?'Good work starts with good people.':page==='labels'?'Give your work a little more context.':'Big ideas start with small steps. Let’s move things forward.'}</p></div><div class="heading-right"><div class="avatar-stack">${data.members.slice(0,4).map(avatar).join('')}</div><button class="btn primary" data-action="${page==='team'?'member':page==='labels'?'label':'new'}">${icon('plus')} ${page==='team'?'Add member':page==='labels'?'New label':'New task'}</button></div></div>${page==='board'?`<div class="stats">${[['board','',total,'Total tasks'],['clock','purple',progress,'In progress'],['check','green',completed,'Completed'],['calendar','orange',overdue,'Overdue']].map(([i,c,n,l],idx)=>`<div class="stat"><div class="stat-icon ${c}">${icon(i)}</div><div><strong>${n}</strong><span>${l}</span></div>${idx===2?`<small>${total?Math.round(completed/total*100):0}% done</small>`:idx===0?'<small>All work</small>':''}</div>`).join('')}</div><div class="board-menu"><div class="tabs"><button class="tab ${view==='board'?'active':''}" data-view="board">${icon('board')} Board <small>${total}</small></button><button class="tab ${view==='list'?'active':''}" data-view="list">${icon('list')} List</button></div><div class="board-meta">${icon('cloud')} ${cloud()?'Saved in Supabase':'Saved on this device'}</div></div><div class="toolbar"><label class="searchbox">${icon('search')}<input id="search" type="search" value="${esc(search)}" placeholder="Search tasks…" aria-label="Search tasks"></label><select aria-label="Filter by priority" data-filter="priority" class="${filters.priority?'filter-active':''}"><option value="">All priorities</option>${['high','normal','low'].map(p=>`<option value="${p}" ${filters.priority===p?'selected':''}>${p[0].toUpperCase()+p.slice(1)} priority</option>`).join('')}</select><select aria-label="Filter by assignee" data-filter="assignee" class="${filters.assignee?'filter-active':''}"><option value="">All assignees</option>${data.members.map(m=>`<option value="${m.id}" ${filters.assignee===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select><select aria-label="Filter by label" data-filter="label" class="${filters.label?'filter-active':''}"><option value="">All labels</option>${data.labels.map(l=>`<option value="${l.id}" ${filters.label===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select>${search||Object.values(filters).some(Boolean)?'<button class="clear" data-action="clear">Clear</button>':''}<span class="filter-count">${filtered().length} task${filtered().length!==1?'s':''} in view</span></div><div id="board-content">${boardContent()}</div><div class="board-footer"><span>${icon('help')} Drag to move. Click a task for the details.</span><span><i class="green-dot"></i>${cloud()?'Guest-owned · Synced to Supabase':'All changes saved locally'}</span></div>`:page==='team'?`<div class="team-grid" style="margin-top:30px">${data.members.map(m=>`<div class="member-card">${avatar(m)}<div><strong>${esc(m.name)}</strong><small>${data.tasks.filter(t=>t.assignee_ids.includes(m.id)).length} assigned tasks</small></div></div>`).join('')||'<div class="empty">Your next great collaboration starts here. Add your first member.</div>'}</div><div class="settings-card"><h3>A team for your workspace</h3><p>Members help you organize assignments. They are people records in your guest workspace; adding a member does not send an invitation or give them access to your tasks.</p></div>`:`<div class="settings-card"><h3>Workspace labels</h3><p>Add context to tasks, then filter your board by what matters.</p><div class="choices">${data.labels.map(l=>`<span class="tag" style="--tagcolor:${esc(l.color)};padding:8px 12px;font-size:12px">${esc(l.name)}</span>`).join('')||'No labels yet.'}</div><button class="btn" data-action="label">${icon('plus')} Create label</button></div>`}</div></main></div>`;bind()}
function bind(){ $$('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()});$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});$$('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b));$('#search')?.addEventListener('input',e=>{search=e.target.value;$('#board-content').innerHTML=boardContent();bindTasks();$('.filter-count')&&( $('.filter-count').textContent=`${filtered().length} tasks in view`)});$$('[data-filter]').forEach(s=>s.onchange=()=>{filters[s.dataset.filter]=s.value;render()});bindTasks()}
function bindTasks(){ $$('[data-task]').forEach(c=>{c.onclick=()=>openTask(c.dataset.task);c.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openTask(c.dataset.task)}};c.ondragstart=e=>{if(busy){e.preventDefault();return}e.dataTransfer.setData('text/plain',c.dataset.task);e.dataTransfer.effectAllowed='move';c.classList.add('dragging')};c.ondragend=()=>{$$('.dragover,.dragging').forEach(x=>x.classList.remove('dragover','dragging'))}});$$('.column').forEach(col=>{col.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='move';col.classList.add('dragover')};col.ondragleave=e=>{if(!col.contains(e.relatedTarget))col.classList.remove('dragover')};col.ondrop=async e=>{e.preventDefault();col.classList.remove('dragover');const t=data.tasks.find(x=>x.id===e.dataTransfer.getData('text/plain'));if(!t||t.status===col.dataset.status||busy)return;busy=true;try{await saveTask({...t,status:col.dataset.status});toast(`Moved to ${statusName(col.dataset.status)}`)}catch(e){toast(e.message)}finally{busy=false;render()}}});$$('#board-content [data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b))}
function action(a,b){if(a==='new')openTask(null,b?.dataset.status);if(a==='member')entityModal('member');if(a==='label')entityModal('label');if(a==='connect')connectModal();if(a==='clear'){search='';filters={priority:'',assignee:'',label:''};render()}if(a==='help')helpModal();if(a==='retry')init()}
function show(html,modal=false){lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="backdrop ${modal?'modal-wrap':''}"><section class="${modal?'modal':'drawer'}" role="dialog" aria-modal="true" aria-label="${modal?'Workspace dialog':'Task details'}">${html}</section></div>`;$('.backdrop').onclick=e=>{if(e.target===$('.backdrop')&&!busy)close()};$$('[data-close]').forEach(b=>b.onclick=()=>{if(!busy)close()});setTimeout(()=>{const dialog=$('.modal,.drawer');if(dialog)$('input,button,textarea,select',dialog)?.focus()},40)}
function close(){if(busy)return;$('#overlay').innerHTML='';opened=null;lastFocus?.isConnected&&lastFocus.focus()}
document.addEventListener('keydown',e=>{if(!$('.backdrop'))return;if(e.key==='Escape')close();if(e.key==='Tab'){const a=$$('button:not(:disabled),input,select,textarea,[tabindex="0"],a[href]',$('.backdrop')).filter(el=>el.offsetParent!==null);if(!a.length)return;if(e.shiftKey&&document.activeElement===a[0]){e.preventDefault();a.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===a.at(-1)){e.preventDefault();a[0].focus()}}});
function head(title,sub=''){return `<div class="dialog-head"><div><h2>${title}</h2>${sub?`<small>${sub}</small>`:''}</div><button class="icon-btn" data-close aria-label="Close dialog">${icon('close')}</button></div>`}
function openTask(id,status='todo'){opened=id;detailTab='comments';const t=data.tasks.find(t=>t.id===id)||{id:uuid(),title:'',description:'',status:status||'todo',priority:'normal',due_date:'',assignee_ids:[],label_ids:[]};show(`${head(id?'Task details':'Make something happen',id?'YOUR WORK, IN FOCUS':'A SMALL STEP FORWARD')}<form id="task-form"><input class="form-title" name="title" placeholder="Give your task a name…" aria-label="Task title" value="${esc(t.title)}" required maxlength="200"><div class="field-row"><label class="field"><span>Status</span><select name="status">${statuses.map(([s,n])=>`<option value="${s}" ${s===t.status?'selected':''}>${n}</option>`).join('')}</select></label><label class="field"><span>Priority</span><select name="priority">${['low','normal','high'].map(p=>`<option value="${p}" ${p===t.priority?'selected':''}>${p[0].toUpperCase()+p.slice(1)}</option>`).join('')}</select></label></div><label class="field"><span>Description</span><textarea name="description" placeholder="Add a little context…" maxlength="10000">${esc(t.description)}</textarea></label><label class="field"><span>Due date</span><input type="date" name="due_date" value="${esc(t.due_date||'')}"></label><span class="field-label">Assignees</span><div class="choices">${data.members.map(m=>`<label class="choice"><input type="checkbox" name="assignees" value="${m.id}" ${t.assignee_ids.includes(m.id)?'checked':''}>${avatar(m)}${esc(m.name)}</label>`).join('')||'<span class="subtitle">Add members from the Team members page.</span>'}</div><span class="field-label">Labels</span><div class="choices">${data.labels.map(l=>`<label class="choice"><input type="checkbox" name="labels" value="${l.id}" ${t.label_ids.includes(l.id)?'checked':''}><span class="tag" style="--tagcolor:${esc(l.color)}">${esc(l.name)}</span></label>`).join('')||'<span class="subtitle">Create labels from the Labels page.</span>'}</div><div class="form-error" id="task-error" role="alert"></div><div class="form-actions">${id?'<button type="button" class="danger" id="delete-task">Delete task</button>':'<span style="margin-right:auto"></span>'}<button type="button" class="btn" data-close>Cancel</button><button class="btn primary" type="submit">${id?'Save changes':'Create task'}</button></div></form>${id?`<div class="detail-tabs"><button class="tab active" data-detail="comments">${icon('comment')} Comments <small>${countComments(t)}</small></button><button class="tab" data-detail="activity">${icon('clock')} Activity</button></div><div id="task-timeline"></div>`:''}`);
$('#task-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),title=String(f.get('title')).trim();if(!title){$('#task-error').textContent='Give this task a title first.';return}const updated={...t,title,description:String(f.get('description')).trim(),status:f.get('status'),priority:f.get('priority'),due_date:f.get('due_date')||null,assignee_ids:f.getAll('assignees'),label_ids:f.getAll('labels')};busy=true;const btn=$('button[type=submit]',e.target);btn.disabled=true;btn.textContent='Saving…';try{await saveTask(updated);busy=false;close();render();toast(id?'Task updated. A little progress.':'A new task, a fresh start.')}catch(err){$('#task-error').textContent=err.message}finally{busy=false;btn.disabled=false;btn.textContent=id?'Save changes':'Create task'}};
$('#delete-task')?.addEventListener('click',async()=>{if(!confirm('Delete this task and its comments? This cannot be undone.'))return;busy=true;try{if(cloud()){await api(`tasks?id=eq.${t.id}`,'DELETE');await load()}else{data.tasks=data.tasks.filter(x=>x.id!==t.id);data.comments=data.comments.filter(x=>x.task_id!==t.id);data.activity=data.activity.filter(x=>x.task_id!==t.id);persist()}busy=false;close();render();toast('Task deleted')}catch(err){$('#task-error').textContent=err.message}finally{busy=false}});
$$('[data-detail]').forEach(b=>b.onclick=()=>{detailTab=b.dataset.detail;$$('[data-detail]').forEach(x=>x.classList.toggle('active',x===b));renderTimeline(t.id)});if(id)renderTimeline(t.id)}
function renderTimeline(id){const items=(detailTab==='comments'?data.comments:data.activity).filter(x=>x.task_id===id).sort((a,b)=>a.created_at.localeCompare(b.created_at));$('#task-timeline').innerHTML=`${detailTab==='comments'?'<form class="comment-form" id="comment-form"><textarea name="body" aria-label="Write a comment" placeholder="Leave a thought, a question, a little encouragement…" required maxlength="5000"></textarea><div class="form-error" id="comment-error" role="alert"></div><button class="btn primary" type="submit">Post comment</button></form>':''}<div class="timeline">${items.map(x=>`<div class="event">${detailTab==='comments'?'<span class="avatar" style="--color:#708e7b">Y</span>':`<span class="event-icon">${icon('clock')}</span>`}<div class="event-content"><strong>${detailTab==='comments'?'You':'Workspace activity'}</strong><time datetime="${esc(x.created_at)}">${fmtTime(x.created_at)}</time><p>${esc(x.body)}</p></div></div>`).join('')||`<div class="empty">${detailTab==='comments'?'Start a conversation. Every good idea begins somewhere.':'The story of this task will appear here.'}</div>`}</div>`;$('#comment-form')?.addEventListener('submit',async e=>{e.preventDefault();const body=String(new FormData(e.target).get('body')).trim();if(!body)return;const btn=$('button',e.target);btn.disabled=true;busy=true;try{if(cloud()){await api('comments','POST',{task_id:id,body,user_id:session.user.id});await load()}else{data.comments.push({id:uuid(),task_id:id,body,created_at:new Date().toISOString()});persist()}renderTimeline(id);const count=$('[data-detail=comments] small');if(count)count.textContent=data.comments.filter(c=>c.task_id===id).length;toast('Comment added')}catch(err){$('#comment-error').textContent=err.message}finally{busy=false;btn.disabled=false}})}
function entityModal(kind){const member=kind==='member';show(`${head(member?'Good work needs good people.':'A label for what matters.')}<form id="entity-form"><label class="field"><span>${member?'Member name':'Label name'}</span><input name="name" required maxlength="80" placeholder="${member?'e.g. Alex Morgan':'e.g. Customer feedback'}"></label><label class="field"><span>Color</span><input type="color" name="color" value="${member?colors[data.members.length%colors.length]:'#8ba3bd'}" style="height:42px;padding:5px"></label><div id="entity-error" class="form-error" role="alert"></div><button class="btn primary" type="submit">${icon('plus')} ${member?'Add member':'Create label'}</button></form>`,true);$('#entity-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')).trim();if(!name)return;const bucket=member?'members':'labels';if(data[bucket].some(x=>x.name.toLowerCase()===name.toLowerCase())){$('#entity-error').textContent='This name already exists.';return}const entity={id:uuid(),name,color:f.get('color')};busy=true;const btn=$('button[type=submit]',e.target);btn.disabled=true;try{if(cloud()){await api(member?'team_members':'labels','POST',{...entity,user_id:session.user.id});await load()}else{data[bucket].push(entity);persist()}busy=false;close();render();toast(member?'A new face in the workspace.':'Label created')}catch(err){$('#entity-error').textContent=err.message}finally{busy=false;btn.disabled=false}}}
function connectModal(){show(`${head('Make this workspace yours.')}<p>Connect a Supabase project to save tasks securely with an anonymous guest session. Enable anonymous sign-ins and run the included <a href="schema.sql" download>database schema</a> first.</p><div class="notice">${cloud()?'This browser is connected to Supabase.':'Demo tasks stay in this browser. Connecting opens your cloud workspace; demo tasks are not uploaded.'}</div><form id="connect-form"><label class="field"><span>Supabase project URL</span><input name="url" type="url" required placeholder="https://your-project.supabase.co" value="${esc(config?.url||'')}"></label><label class="field"><span>Public anon / publishable key</span><input name="key" required placeholder="sb_publishable_… or public anon JWT" value="${esc(config?.key||'')}" autocomplete="off"></label><p>Use the public key only. Your guest session and Row Level Security protect your data. Never enter a service role key.</p><div id="connect-error" class="form-error" role="alert"></div><button class="btn primary" type="submit">${icon('cloud')} Connect workspace</button>${cloud()?'<button class="btn" type="button" id="disconnect">Back to local demo</button>':''}</form><p><a href="schema.sql" download>Download SQL schema</a> · <a href="README.md" download>Setup guide</a></p>`,true);$('#connect-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),url=String(f.get('url')).replace(/\/+$/,''),key=String(f.get('key')).trim();const err=$('#connect-error');try{const u=new URL(url);if(u.protocol!=='https:'||u.username||u.password||u.pathname!=='/'||u.search||u.hash)throw Error('Use the HTTPS project origin, without a path.');if(key.startsWith('sb_secret_'))throw Error('Use a publishable key, never a secret key.');if(key.split('.').length===3){const payload=JSON.parse(atob(key.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));if(payload.role!=='anon')throw Error('Use the public anon key. Service role keys are not allowed.')}}catch(ex){err.textContent=ex.message;return}const oldConfig=config,oldSession=session,oldData=data;config={url,key};session=oldConfig?.url===url&&oldConfig?.key===key?oldSession:null;busy=true;const btn=$('button[type=submit]',e.target);btn.disabled=true;btn.textContent='Connecting…';try{await load();localStorage.setItem('forma-connection',JSON.stringify(config));localStorage.removeItem('forma-demo-mode');loadError='';busy=false;close();render();toast('Connected. Your private cloud workspace is ready.')}catch(ex){config=oldConfig;session=oldSession;data=oldData;if(session)localStorage.setItem('forma-session',JSON.stringify(session));else localStorage.removeItem('forma-session');err.textContent=ex.message}finally{busy=false;btn.disabled=false;btn.textContent='Connect workspace'}};$('#disconnect')?.addEventListener('click',async()=>{config=null;session=null;localStorage.setItem('forma-demo-mode','true');localStorage.removeItem('forma-connection');localStorage.removeItem('forma-session');await load();loadError='';close();render();toast('Returned to your local demo')})}
function helpModal(){show(`${head('A little help, a lot of possibility.')}<p><strong>Make your next move.</strong><br>Drag cards between columns, or open a task and change its status. On touch screens and with a keyboard, the status menu does the same job.</p><p><strong>Bring the details together.</strong><br>Click any task to edit its description, priority, due date, assignees, and labels. Comments and the activity timeline live in the same panel.</p><p><strong>Find your focus.</strong><br>Combine title search with priority, assignee, and label filters. The summary always reflects the whole workspace.</p><p><strong>Your own space.</strong><br>Demo mode saves on this device. Supabase mode uses an anonymous account with private, owner-scoped records. Keep this browser’s storage to retain your guest account.</p><button class="btn primary" data-close>Got it</button>`,true)}
async function init(){busy=true;loadError='';render();try{await load()}catch(e){loadError=e.message;toast(e.message)}finally{busy=false;render()}}
init();
